// ── AJUSTE ESTES DOIS VALORES ────────────────────────────────
const CHAT_ID = -5403036702;                                  // id do grupo (negativo)
const MEMBROS = { 822395388: 'Vini', 1060520015: 'Lidia' };  // from.id -> nome
// Descubra os dois rodando: scripts/checar-bot.sh <token>
// ─────────────────────────────────────────────────────────────

const upd = $input.first().json;
const msg = upd.message || upd.edited_message;
if (!msg) return [];

// 1. autorizacao: precisa ser o grupo certo e um membro conhecido
if (String(msg.chat.id) !== String(CHAT_ID)) return [];
const pessoa = MEMBROS[msg.from.id];
if (!pessoa) return [];

// 2. idempotencia: guarda os ultimos update_id na memoria do workflow
const st = $getWorkflowStaticData('global');
st.vistos = st.vistos || [];
if (st.vistos.includes(upd.update_id)) return [];
st.vistos.push(upd.update_id);
if (st.vistos.length > 300) st.vistos = st.vistos.slice(-300);

const texto = (msg.text || msg.caption || '').trim();
if (!texto) return [];

// 3. pedido de exclusao: sai por outro ramo, sem Gemini e sem prompt.
// Vem antes do teste do numero porque "apagar" nao tem digito nenhum.
const APAGAR = /^\s*(apagar?|apaga|deletar?|excluir?|remover?)\b/i;
const comum = {
  update_id: upd.update_id,
  message_id: msg.message_id,
  chat_id: msg.chat.id,
  pessoa,
  texto,
};
if (APAGAR.test(texto)) {
  return [{ json: {
    ...comum,
    tipo: 'apagar',
    // reply na propria mensagem ou na confirmacao do bot: os dois ids levam ao
    // mesmo lancamento, porque o fluxo guarda ambos ao confirmar
    responde_a: (msg.reply_to_message && msg.reply_to_message.message_id) || 0,
  }}];
}

// 4. triagem: sem numero que pareca dinheiro, nao gasta LLM nem le a planilha
if (!/\d/.test(texto)) return [];

// 5. data de hoje no fuso de Sao Paulo, formato YYYY-MM-DD
const hoje = new Date().toLocaleDateString('sv-SE', { timeZone: 'America/Sao_Paulo' });

return [{ json: { ...comum, tipo: 'lancamento', hoje }}];

// Monta o prompt e o responseSchema a partir do que a PLANILHA diz.
// Cartões e gastos fixos vêm das abas Cartoes e GastosFixos: adicionar um cartão
// novo ou um fixo novo é editar a planilha, nunca este workflow.

// O que foi gasto. Alinhado com a planilha da casa.
const CATEGORIAS = [
  'Mercado', 'Hortifrutti', 'Alimentação', 'Lanches', 'Confraternizações',
  'Farmácia', 'Saúde', 'Academia', 'Assinaturas', 'Combustível', 'Passagem',
  'Transporte', 'Carro', 'Barbeiro', 'Vestuário', 'Educação', 'Moradia',
  'Pets', 'Presentes', 'Lazer', 'Ofertas', 'Dívidas', 'Investimento',
  'Salário', 'Horas Extras', 'Auxílios', 'PLR', 'Outros',
];

// Como foi pago. Os cartões saem da aba Cartoes; o resto é fixo.
const SEM_CARTAO = ['Débito', 'Pix', 'Dinheiro', 'VA', 'Boleto', 'Não informado'];

const src = $('Triagem').first().json;

const cartoes = $('Ler cartões').all()
  .map((i) => String(i.json.nome || '').trim())
  .filter(Boolean);

const fixos = $('Ler gastos fixos').all()
  .map((i) => i.json)
  .filter((f) => String(f.ativo || 'sim').toLowerCase() !== 'nao'
               && String(f.ativo || 'sim').toLowerCase() !== 'não')
  .map((f) => String(f.nome || '').trim())
  .filter(Boolean);

const FORMAS = [...cartoes, ...SEM_CARTAO];

const prompt = [
  'Voce extrai lancamentos financeiros de mensagens em portugues do Brasil.',
  'Hoje e ' + src.hoje + ' (fuso America/Sao_Paulo).',
  '',
  'Devolva um lancamento para CADA gasto ou recebimento citado na mensagem.',
  '"padaria 12 e farmacia 30" sao DOIS lancamentos, nunca um de 42.',
  'Se a mensagem nao registra dinheiro, devolva a lista vazia.',
  'Registre apenas o que JA aconteceu. Lembrete e intencao futura nao sao',
  'lancamento: "lembra de pagar", "preciso pagar", "vou pagar", "vence sexta"',
  '-> lista vazia.',
  'Compra parcelada, porem, JA aconteceu: registre UMA parcela, com o valor',
  'da parcela, e escreva as parcelas na descricao (ex.: "Fone 1/12").',
  '',
  'Categorias permitidas: ' + CATEGORIAS.join(', ') + '.',
  'Formas de pagamento permitidas: ' + FORMAS.join(', ') + '.',
  fixos.length ? 'Gastos fixos da casa: ' + fixos.join(', ') + '.' : '',
  '',
  'Regras:',
  '- tipo = entrada SOMENTE com verbo explicito de dinheiro que entrou: recebi,',
  '  caiu, entrou, ganhei, vendi, salario, pix recebido, reembolso, estorno.',
  '- tipo = investimento para aporte: apliquei, investi, guardei, reserva.',
  '- todo o resto e saida, inclusive comprar presente para alguem. Na duvida, saida.',
  '- valor sempre positivo, em reais, com ponto como separador decimal.',
  '- forma: use o cartao citado ("no nubank" -> o cartao do Nubank de quem enviou).',
  '  Sem forma citada, use "Não informado". Nunca invente cartao.',
  '- uma forma citada uma vez vale para TODOS os gastos da mensagem:',
  '  "mercado 85 e uber 23 no pix" sao dois lancamentos, ambos no Pix.',
  '- resolva datas relativas ("ontem", "sexta") contra a data de hoje.',
  '  Sem data explicita, use hoje.',
  '- categoria obrigatoriamente uma da lista. Se nada encaixar, use Outros.',
  '- fixo: se o lancamento paga um dos gastos fixos da casa, escreva o nome dele',
  '  exatamente como esta na lista. Caso contrario, string vazia.',
  '- descricao curta, ate 40 caracteres, com o estabelecimento quando houver.',
  '- confianca de 0 a 1: quao seguro voce esta do valor, da categoria e da forma.',
  '- nunca invente valor.',
  '',
  'Quem enviou: ' + src.pessoa,
  'Mensagem: ' + src.texto,
].filter(Boolean).join('\n');

const payload = {
  contents: [{ role: 'user', parts: [{ text: prompt }] }],
  generationConfig: {
    temperature: 0,
    responseMimeType: 'application/json',
    responseSchema: {
      type: 'object',
      properties: {
        lancamentos: {
          type: 'array',
          items: {
            type: 'object',
            properties: {
              tipo:      { type: 'string', enum: ['saida', 'entrada', 'investimento'] },
              valor:     { type: 'number' },
              data:      { type: 'string' },
              categoria: { type: 'string', enum: CATEGORIAS },
              forma:     { type: 'string', enum: FORMAS },
              descricao: { type: 'string' },
              fixo:      { type: 'string' },
              confianca: { type: 'number' },
            },
            required: ['tipo', 'valor', 'data', 'categoria', 'forma', 'descricao', 'fixo', 'confianca'],
          },
        },
      },
      required: ['lancamentos'],
    },
  },
};

return [{ json: {
  ...src,
  categorias: CATEGORIAS,
  formas: FORMAS,
  cartoes: $('Ler cartões').all().map((i) => i.json),
  fixos: $('Ler gastos fixos').all().map((i) => i.json),
  payload,
}}];

// Dinheiro é determinístico: o modelo propõe, aqui a casa decide.
// Emite uma linha por lançamento — o nó do Sheets grava todas de uma vez.

const src = $('Montar prompt').first().json;
const resp = $input.first().json;

// tira acento e caixa para comparar o que o modelo devolveu com as listas
const norm = (s) => String(s || '')
  .normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();

const acharNaLista = (valor, lista) => {
  const alvo = norm(valor);
  return lista.find((x) => norm(x) === alvo) || null;
};

let p;
try {
  p = JSON.parse(resp.candidates[0].content.parts[0].text);
} catch (e) {
  return [];                          // modelo devolveu algo ilegivel: ignora
}
const itens = Array.isArray(p.lancamentos) ? p.lancamentos : [];
if (!itens.length) return [];         // nao era lancamento: silencio

// dia de fechamento e de vencimento por cartao, vindos da aba Cartoes
const cartoes = {};
for (const c of src.cartoes || []) {
  const nome = String(c.nome || '').trim();
  if (!nome) continue;
  cartoes[norm(nome)] = {
    nome,
    fechamento: Number(c.dia_fechamento) || 0,
    vencimento: Number(c.dia_vencimento) || 0,
  };
}

const fixosPorNome = {};
for (const f of src.fixos || []) {
  const nome = String(f.nome || '').trim();
  if (nome) fixosPorNome[norm(nome)] = { nome, categoria: String(f.categoria || '').trim() };
}
const nomesFixos = Object.values(fixosPorNome).map((f) => f.nome);

// Em que fatura esse gasto cai. Devolve a competencia do VENCIMENTO — que é o
// mes em que o dinheiro sai da conta, e é assim que a planilha da casa pensa.
function competenciaFatura(data, cartao) {
  if (!cartao || !cartao.fechamento) return '';
  const [ano, mes, dia] = data.split('-').map(Number);
  // gasto depois do fechamento entra na fatura que fecha no mes seguinte
  let mesFecha = dia <= cartao.fechamento ? mes : mes + 1;
  // vencimento antes do fechamento significa que a fatura vence no mes seguinte
  let mesVence = cartao.vencimento > cartao.fechamento ? mesFecha : mesFecha + 1;
  let anoVence = ano;
  while (mesVence > 12) { mesVence -= 12; anoVence += 1; }
  return `${anoVence}-${String(mesVence).padStart(2, '0')}`;
}

const saida = [];
for (const item of itens) {
  const valor = Math.round(Number(item.valor) * 100) / 100;
  if (!isFinite(valor) || valor <= 0) continue;

  const data = /^\d{4}-\d{2}-\d{2}$/.test(item.data) ? item.data : src.hoje;
  const forma = acharNaLista(item.forma, src.formas) || 'Não informado';
  const fixo = acharNaLista(item.fixo, nomesFixos) || '';

  // gasto fixo tem categoria cadastrada na planilha: ela vale mais que o palpite
  // do modelo, que ja chamou "internet" de Assinaturas e de Moradia
  const catDoFixo = fixo ? fixosPorNome[norm(fixo)].categoria : '';
  const categoria = acharNaLista(catDoFixo, src.categorias)
                 || acharNaLista(item.categoria, src.categorias)
                 || 'Outros';
  const tipo = ['entrada', 'investimento'].includes(item.tipo) ? item.tipo : 'saida';

  saida.push({ json: {
    update_id: src.update_id,
    data,
    competencia: data.slice(0, 7),      // o mes do gasto, para o orcamento
    competencia_fatura: competenciaFatura(data, cartoes[norm(forma)]),
    criado_em: new Date().toISOString(),
    tipo,
    valor,
    categoria,
    forma,
    descricao: String(item.descricao || '').slice(0, 60),
    pessoa: src.pessoa,
    fixo,
    mensagem: src.texto,
    confianca: Math.round(Number(item.confianca || 0) * 100) / 100,
  }});
}

return saida;

// Uma mensagem só no grupo, mesmo quando a mensagem original tinha vários gastos.
// Confirmar cada lançamento separado transformaria o grupo num log.

const linhas = $input.all().map((i) => i.json);
if (!linhas.length) return [];

const src = $('Montar prompt').first().json;
const brl = (v) => 'R$ ' + v.toFixed(2).replace('.', ',');
const sinal = { saida: '−', entrada: '+', investimento: '↗' };

const total = linhas.reduce((a, l) => a + (l.tipo === 'entrada' ? l.valor : -l.valor), 0);
const duvidoso = linhas.some((l) => l.confianca < 0.7);

let texto;
if (linhas.length === 1) {
  const l = linhas[0];
  texto = `${sinal[l.tipo]} ${brl(l.valor)} · ${l.categoria}`
        + (l.forma !== 'Não informado' ? ` · ${l.forma}` : '')
        + (l.fixo ? ` · fixo: ${l.fixo}` : '');
} else {
  texto = `${linhas.length} lançamentos\n`
        + linhas.map((l) => `${sinal[l.tipo]} ${brl(l.valor)} · ${l.categoria}`
            + (l.forma !== 'Não informado' ? ` · ${l.forma}` : '')).join('\n')
        + `\nsaldo da mensagem: ${brl(Math.abs(total))}`;
}
if (duvidoso) texto += '\n⚠️ confira: não tive certeza de algum campo';

return [{ json: {
  chat_id: src.chat_id,
  message_id: src.message_id,
  texto_resposta: texto,
}}];

// Guarda a ponte entre a conversa e a planilha: qual mensagem gerou quais
// linhas.
//
// Sem isso, responder "apagar" a uma confirmação não teria como saber o que
// apagar: o Telegram entrega a mensagem respondida sem o reply dela, então não
// há como seguir a cadeia de volta até o lançamento. Ficam guardados os dois
// ids — o da mensagem de quem gastou e o da confirmação do bot — porque na
// prática as pessoas respondem tanto a uma quanto à outra.

const enviada = $input.first().json;
const src = $('Montar prompt').first().json;
const linhas = $('Validar').all().map((i) => i.json);

const st = $getWorkflowStaticData('global');
st.confirmacoes = st.confirmacoes || {};

const chaves = linhas.map((l) => ({
  update_id: String(l.update_id),
  criado_em: l.criado_em,
  valor: l.valor,
  descricao: l.descricao,
}));

const idDaConfirmacao = (enviada && enviada.result && enviada.result.message_id) || enviada.message_id;
for (const id of [src.message_id, idDaConfirmacao]) {
  if (id) st.confirmacoes[String(id)] = chaves;
}

// O mapa não pode crescer para sempre. 400 mensagens são meses de uso da casa,
// e o que cai fora ainda pode ser apagado pelo dashboard.
const ids = Object.keys(st.confirmacoes);
if (ids.length > 400) {
  for (const id of ids.slice(0, ids.length - 400)) delete st.confirmacoes[id];
}

return [];

// Decide o que "apagar" quer dizer, e acha as linhas na planilha lida agora.
//
// Dois jeitos de pedir, e a diferença importa: respondendo a uma mensagem, o
// alvo é aquele lançamento, de qualquer dia; sem responder nada, o alvo é o
// último que a própria pessoa registrou. Ninguém apaga o lançamento do outro
// sem apontar para ele.

const src = $('Triagem').first().json;
const linhas = $input.all().map((i) => i.json);
const mapa = $getWorkflowStaticData('global').confirmacoes || {};

const norm = (v) => String(v ?? '').trim().toLowerCase();
const centavos = (v) => {
  const bruto = String(v ?? '').replace(/[R$\s]/g, '');
  const limpo = bruto.includes(',') ? bruto.replace(/\./g, '').replace(',', '.') : bruto;
  const n = Number(limpo);
  return isFinite(n) ? Math.round(n * 100) : NaN;
};
const chaveDe = (l) => ({
  update_id: String(l.update_id), criado_em: String(l.criado_em),
  valor: l.valor, descricao: l.descricao,
});

let chaves = [];
let alvo = '';

if (src.responde_a) {
  chaves = mapa[String(src.responde_a)] || [];
  alvo = 'o lançamento dessa mensagem';
  if (!chaves.length) {
    return [{ json: { nada: true, ...src,
      recado: 'não sei a que lançamento essa mensagem se refere. '
            + 'Responda à confirmação de um gasto recente, ou apague pelo dashboard.' } }];
  }
} else {
  const suas = linhas.filter((l) => norm(l.pessoa) === norm(src.pessoa));
  if (!suas.length) {
    return [{ json: { nada: true, ...src, recado: 'não achei nenhum lançamento seu para apagar.' } }];
  }
  // a última mensagem sua, com todos os gastos que ela gerou
  const ultima = suas.reduce((a, b) => (String(a.criado_em) > String(b.criado_em) ? a : b));
  chaves = suas.filter((l) => String(l.update_id) === String(ultima.update_id)).map(chaveDe);
  alvo = 'seu último lançamento';
}

// Mesmo com a chave em mãos, confere valor e descrição: a planilha é editada à
// mão também, e apagar a linha errada é pior que não apagar nada.
const achadas = [];
for (const chave of chaves) {
  const casadas = linhas.filter(
    (l) => String(l.update_id) === String(chave.update_id)
        && String(l.criado_em) === String(chave.criado_em)
        && centavos(l.valor) === centavos(chave.valor)
        && norm(l.descricao) === norm(chave.descricao),
  );
  if (casadas.length === 1 && Number(casadas[0].row_number) >= 2) {
    achadas.push({ ...chave, row_number: Number(casadas[0].row_number), linha: casadas[0] });
  }
}

if (!achadas.length) {
  return [{ json: { nada: true, ...src,
    recado: 'esse lançamento não está mais na planilha — alguém já apagou.' } }];
}

// de baixo para cima, senão o primeiro delete faz os números seguintes escorregarem
achadas.sort((a, b) => b.row_number - a.row_number);
return achadas.map((a) => ({ json: { ...a, nada: false, alvo, ...src } }));

// A resposta no grupo. Diz o que saiu da planilha, com valor e categoria: quem
// pediu precisa reconhecer o que sumiu, senão fica a dúvida de ter apagado
// outra coisa.

const itens = $input.all().map((i) => i.json);
const src = $('Triagem').first().json;
const brl = (v) => 'R$ ' + Number(v).toFixed(2).replace('.', ',');

const primeiro = itens[0] || {};
if (!itens.length || primeiro.nada) {
  return [{ json: {
    chat_id: src.chat_id,
    message_id: src.message_id,
    texto_resposta: primeiro.recado || 'não achei o que apagar.',
  } }];
}

const apagados = itens.filter((i) => !i.nada);
const descrever = (i) => {
  const l = i.linha || {};
  return `− ${brl(l.valor)} · ${l.categoria || 'sem categoria'}`
       + (l.forma && l.forma !== 'Não informado' ? ` · ${l.forma}` : '');
};

const texto = apagados.length === 1
  ? `apaguei ${primeiro.alvo}:\n${descrever(apagados[0])}`
  : `apaguei ${apagados.length} lançamentos de ${primeiro.alvo}:\n`
    + apagados.map(descrever).join('\n');

return [{ json: {
  chat_id: src.chat_id,
  message_id: src.message_id,
  texto_resposta: texto,
} }];
